import {wallSegments,wallPoint,rectInside,fitRect} from './room-geometry.mjs';
import {doorHitsFurniture} from './room-openings.mjs';
import {initialProject,validate,footprint,LABELS} from './room-model.mjs';
export const FURNITURE={sofa:{width:2,depth:.85},bed:{width:1.6,depth:2},desk:{width:1.2,depth:.6},wardrobe:{width:1.6,depth:.6}};
export const STYLES=[{name:'Светлая комната',hint:'Молочный · натуральное дерево',walls:['#ece8de','#ece8de','#ece8de','#ece8de'],floor:'#c5a77d'},{name:'Тёплое дерево',hint:'Песочный · медовый дуб',walls:['#bda58b','#e4d7c5','#e4d7c5','#e4d7c5'],floor:'#b58e61'},{name:'Оливковый акцент',hint:'Приглушённый зелёный · светлый дуб',walls:['#829078','#e4dfd2','#e4dfd2','#e4dfd2'],floor:'#c5a77d'}];
export function overlap(a,b){const A=footprint(a),B=footprint(b);return a.x<b.x+B.w-.001&&b.x<a.x+A.w-.001&&a.y<b.y+B.d-.001&&b.y<a.y+A.d-.001;}
export function doorZone(p,o){const a=wallPoint(p,o.wall,o.offset),b=wallPoint(p,o.wall,o.offset+o.width),n=wallSegments(p)[o.wall].normal,points=[a,b,[a[0]+n[0]*.8,a[1]+n[1]*.8],[b[0]+n[0]*.8,b[1]+n[1]*.8]],xs=points.map(v=>v[0]),ys=points.map(v=>v[1]);return {x:Math.min(...xs),y:Math.min(...ys),width:Math.max(...xs)-Math.min(...xs),depth:Math.max(...ys)-Math.min(...ys),rotation:0};}
function blocksOpening(p,f,o){return (o.type==='door'||(f.type==='wardrobe'&&o.sill<1.9))&&overlap(f,doorZone(p,o));}
export function warnings(p){const result=[];p.furniture.forEach((f,i)=>{p.furniture.slice(0,i).forEach((b,j)=>{if(overlap(f,b))result.push({indices:[i,j],text:`${LABELS[f.type]} и ${LABELS[b.type].toLowerCase()} пересекаются. Раздвиньте их на плане.`});});if(p.openings.some(o=>o.type==='door'&&doorHitsFurniture(p,o,f)))result.push({indices:[i],text:`${LABELS[f.type]} находится перед дверью и мешает её открыванию. Переместите предмет или измените схему двери.`});else if(p.openings.some(o=>o.type==='door'&&overlap(f,doorZone(p,o))))result.push({indices:[i],text:`${LABELS[f.type]} находится перед дверью. Оставьте место для прохода.`});if(f.type==='wardrobe'&&p.openings.some(o=>o.type==='window'&&blocksOpening(p,f,o)))result.push({indices:[i],text:'Шкаф стоит перед окном. Переместите его, чтобы сохранить доступ к окну.'});});return result;}
export function placeFurniture(p,type){const f={type,...FURNITURE[type],rotation:0,x:0,y:0};for(let y=0;y<=p.width-f.depth+.001;y+=.1)for(let x=0;x<=p.length-f.width+.001;x+=.1){f.x=+x.toFixed(2);f.y=+y.toFixed(2);if(rectInside(p,f.x,f.y,f.width,f.depth)&&!p.furniture.some(b=>overlap(f,b))&&!p.openings.some(o=>blocksOpening(p,f,o)))return {...f};}return fitRect(p,{...f,x:0,y:0});}
export function template(kind,base=initialProject()){const p=structuredClone(base);p.kind=kind;p.name=`Моя ${kind==='Гостиная'?'гостиная':kind==='Спальня'?'спальня':'комната — кабинет'}`;p.furniture=[];for(const type of kind==='Спальня'?['bed','wardrobe']:kind==='Кабинет'?['desk','wardrobe']:['sofa','desk'])p.furniture.push(placeFurniture(p,type));return validate(p);}
export function moveFurniture(p,index,x,y){const f=p.furniture[index],{w,d}=footprint(f),maxX=p.length-w,maxY=p.width-d;const snap=(v,max)=>{const clamped=Math.max(0,Math.min(max,v));if(clamped<.12)return 0;if(max-clamped<.12)return max;return Math.round(clamped*100)/100;};const candidate={...f,x:snap(x,maxX),y:snap(y,maxY)};return rectInside(p,candidate.x,candidate.y,w,d)?candidate:{...f};}
export function history(initial){let current=structuredClone(initial),past=[],future=[];return {get current(){return structuredClone(current);},get canUndo(){return past.length>0;},get canRedo(){return future.length>0;},set(next){validate(next);if(JSON.stringify(current)===JSON.stringify(next))return;past.push(current);if(past.length>60)past.shift();current=structuredClone(next);future=[];},undo(){if(past.length){future.push(current);current=past.pop();}return this.current;},redo(){if(future.length){past.push(current);current=future.pop();}return this.current;}};}
